function heroBackdrop(){
  heroCtx.setTransform(1,0,0,1,0,0);
  heroCtx.clearRect(0,0,heroGeo.W,heroGeo.H);
  const g=heroCtx.createRadialGradient(heroGeo.cx,heroGeo.cy*0.9,10,
                                       heroGeo.cx,heroGeo.cy,heroGeo.H*0.75);
  g.addColorStop(0,'#181a22'); g.addColorStop(1,'#0a0b0f');
  heroCtx.fillStyle=g; heroCtx.fillRect(0,0,heroGeo.W,heroGeo.H);
}
function renderHero(t){
  t=((t%1)+1)%1;
  heroBackdrop();
  renderCoin(heroCtx, heroGeo, t, MAT.hero, heroFront, heroBack);
}

