function renderEdition(ed, el){
  const t=(el*ed.def.speed+ed.def.phase)%1;
  ed.ctx.setTransform(1,0,0,1,0,0);
  ed.ctx.clearRect(0,0,ed.geo.W,ed.geo.H);
  const g=ed.ctx.createRadialGradient(ed.geo.cx,ed.geo.cy,4,ed.geo.cx,ed.geo.cy,ed.geo.H*0.7);
  g.addColorStop(0,'#15161d'); g.addColorStop(1,'#0b0c10');
  ed.ctx.fillStyle=g; ed.ctx.fillRect(0,0,ed.geo.W,ed.geo.H);
  renderCoin(ed.ctx, ed.geo, t, ed.def.mat, ed.def.content.front, ed.def.content.back);
}

/* ---------------- animation loop + public API ---------------- */
const LOOP=15; // seconds per hero revolution
let running=true, rafId=null, clock0=null;
function frame(now){
  if(clock0===null) clock0=now;
  const el=(now-clock0)/1000;
  renderHero((el/LOOP)%1);
  for(const ed of editions) renderEdition(ed, el);
  rafId=requestAnimationFrame(frame);
}
function pause(){ running=false; if(rafId){cancelAnimationFrame(rafId); rafId=null;} }
function play(){ if(!running){ running=true; clock0=null; rafId=requestAnimationFrame(frame);} }

